1	package wallet
2	
3	import (
4		"errors"
5		"sync"
6		"testing"
7		"time"
8	)
9	
10	// 本文件为大额代付批准功能补充回归保障：不同使用账户各自持有效设备会话、
11	// 共用同一条策略的共享累计额度时，并发批准各自的待审批请求只能按整条策略
12	// 的现存预留加已结算实际费用合计放行——待审批不占额度，出资账户余额充足
13	// 也不能让两笔合计超过累计上限的批准都成功。
14	//
15	// 固定场景（见 setupSharedQuotaApproveContest）：
16	//   - 出资账户 payer 初始可用余额 200、预留 0；使用账户 u1/u2 各自余额为 0、
17	//     分别持有绑定自有设备的有效会话 s1/d1、s2/d2；
18	//   - 策略 p-shared 允许 u1、u2 申请：单次上限 60、共享累计上限 100、
19	//     审批门槛 10、审批等待 1 小时，关闭预留超时；
20	//   - u1、u2 各提交一笔预估费用 60 的申请，两笔使用相同请求编号 share-r，
21	//     但请求按使用账户维度识别，因此仍是各自账户下相互独立的两笔请求；
22	//   - 两笔费用严格超过门槛且申请时现存预留与已花费均为 0（0+60 ≤ 100），
23	//     都进入待审批：payer 仍为可用 200 / 预留 0，策略预留与已花费均为 0，
24	//     账本只有两条零金额待审批留痕。
25	const (
26		contestPolicyID        = "p-shared"
27		contestRequestID       = "share-r"
28		contestFee       int64 = 60
29		contestActualFee int64 = 40
30		contestPayerInit int64 = 200
31		contestPerReq    int64 = 60
32		contestMaxTotal  int64 = 100
33		contestThreshold int64 = 10
34	)
35	
36	// setupSharedQuotaApproveContest 构造上述固定场景，提交两笔申请并断言起点：
37	// 两笔均待审批、提交与等待截止时间各自独立记录；payer 可用 200 / 预留 0；
38	// 策略预留总额 0、已花费总额 0；账本恰有两条待审批留痕，无任何资金记录。
39	// 返回提交时刻（两笔相同）与等待截止时刻（两笔相同）。
40	func setupSharedQuotaApproveContest(t *testing.T) (*Wallet, *clock, time.Time, time.Time) {
41		t.Helper()
42		w, c := newTestWallet()
43		mustAccount(t, w, "payer", contestPayerInit)
44		mustAccount(t, w, "u1", 0)
45		mustAccount(t, w, "u2", 0)
46		if _, err := w.CreateSession("s1", "u1", "d1", c.t.Add(24*time.Hour)); err != nil {
47			t.Fatal(err)
48		}
49		if _, err := w.CreateSession("s2", "u2", "d2", c.t.Add(24*time.Hour)); err != nil {
50			t.Fatal(err)
51		}
52		if _, err := w.CreateSession("sa", "payer", "d-approve", c.t.Add(24*time.Hour)); err != nil {
53			t.Fatal(err)
54		}
55		if err := w.SavePolicy(PolicySpec{
56			ID:                contestPolicyID,
57			PayerAccountID:    "payer",
58			AllowedAccountIDs: []string{"u1", "u2"},
59			Operation:         "charge",
60			Payee:             "shop",
61			StartsAt:          c.t.Add(-time.Hour),
62			EndsAt:            c.t.Add(24 * time.Hour),
63			MaxPerRequest:     contestPerReq,
64			MaxTotal:          contestMaxTotal,
65			ApprovalThreshold: contestThreshold,
66			ApprovalWait:      time.Hour,
67			// MaxReserveDuration 留空（零）：关闭预留超时。
68		}); err != nil {
69			t.Fatal(err)
70		}
71	
72		apply := func(account, session, device string) RequestView {
73			req, err := w.Apply(RequestInput{
74				PolicyID:     contestPolicyID,
75				RequestID:    contestRequestID,
76				AccountID:    account,
77				SessionID:    session,
78				DeviceID:     device,
79				Operation:    "charge",
80				Payee:        "shop",
81				EstimatedFee: contestFee,
82			})
83			if err != nil {
84				t.Fatalf("apply for %s: %v", account, err)
85			}
86			return req
87		}
88		r1 := apply("u1", "s1", "d1")
89		r2 := apply("u2", "s2", "d2")
90		if r1.State != RequestPendingApproval || r2.State != RequestPendingApproval {
91			t.Fatalf("both requests must be pending approval, got %v and %v", r1.State, r2.State)
92		}
93		if !r1.CreatedAt.Equal(c.t) || !r2.CreatedAt.Equal(c.t) {
94			t.Fatalf("created at = %v / %v, want %v", r1.CreatedAt, r2.CreatedAt, c.t)
95		}
96		wantDeadline := c.t.Add(time.Hour)
97		if !r1.WaitDeadline.Equal(wantDeadline) || !r2.WaitDeadline.Equal(wantDeadline) {
98			t.Fatalf("wait deadlines = %v / %v, want %v", r1.WaitDeadline, r2.WaitDeadline, wantDeadline)
99		}
100		// 待审批不允许有任何预留或决定信息。
101		for _, r := range []RequestView{r1, r2} {
102			if !r.ReservedAt.IsZero() || !r.DecidedAt.IsZero() || r.ApproverAccountID != "" || r.RejectReason != "" {
103				t.Fatalf("pending request must carry no reservation or decision: %+v", r)
104			}
105		}
106	
107		// 待审批不冻结余额、不占用共享累计额度：出资账户仍有 200 可用、零预留，
108		// 策略预留总额与已花费总额也都为零。
109		if bal, _ := w.Balance("payer"); bal != (Balances{Available: contestPayerInit, Reserved: 0}) {
110			t.Fatalf("payer balance after two pending applies = %+v, want {200 0}", bal)
111		}
112		if pv, _ := w.Policy(contestPolicyID); pv.ReservedTotal != 0 || pv.SpentTotal != 0 {
113			t.Fatalf("policy totals after two pending applies = reserved %d spent %d, want 0/0",
114				pv.ReservedTotal, pv.SpentTotal)
115		}
116		// 账本只有两条零金额待审批留痕，出资账户名下没有任何资金记录。
117		all := w.Ledger()
118		if len(all) != 2 {
119			t.Fatalf("ledger after applies = %d entries, want 2 pending entries: %+v", len(all), all)
120		}
121		for _, e := range all {
122			if e.Kind != LedgerPendingApproval || e.Amount != 0 {
123				t.Fatalf("entry = %+v, want zero-amount pending-approval entry", e)
124			}
125		}
126		if got := countKind(all, LedgerPendingApproval); got != 2 {
127			t.Fatalf("pending entries = %d, want 2", got)
128		}
129		if len(w.AccountLedger("payer")) != 0 {
130			t.Fatalf("pending approvals must not create payer money entries: %+v", w.AccountLedger("payer"))
131		}
132		return w, c, c.t, wantDeadline
133	}
134	
135	// contestRequests 按账户编号返回竞争中的两笔请求（同请求编号、不同账户）。
136	func contestRequests(t *testing.T, w *Wallet) (u1req, u2req RequestView) {
137		t.Helper()
138		r1, err := w.Request("u1", contestRequestID)
139		if err != nil {
140			t.Fatal(err)
141		}
142		r2, err := w.Request("u2", contestRequestID)
143		if err != nil {
144			t.Fatal(err)
145		}
146		return r1, r2
147	}
148	
149	// checkContestOutcome 校验“两笔待审批同时批准”后的统一结果，不预设胜出者：
150	//   - winner 账户下的请求已预留 60：带批准决定（出资账户、批准时刻），
151	//     预留时刻即批准时刻；提交时间与等待截止时间保持申请时原值；
152	//   - loser 账户下的请求仍待审批：没有预留计时或任何审批决定字段，提交
153	//     时间与等待截止时间保持原值（失败批准不推进期限、不开始预留计时）；
154	//   - payer 可用 140 / 预留 60；策略预留总额 60、已花费总额 0；
155	//   - 原有两条待审批留痕保留；只为胜出请求新增一条 payer 的 60 预留记录与
156	//     一条使用账户的零金额批准记录；失败批准不新增资金记录或审批决定。
157	func checkContestOutcome(t *testing.T, w *Wallet, winner, loser string,
158		createdAt, waitDeadline, approveAt time.Time) {
159		t.Helper()
160		if winner == loser {
161			t.Fatalf("winner and loser must be different accounts, got %q", winner)
162		}
163	
164		winReq, err := w.Request(winner, contestRequestID)
165		if err != nil {
166			t.Fatal(err)
167		}
168		if winReq.State != RequestReserved {
169			t.Fatalf("winner %s state = %v, want reserved", winner, winReq.State)
170		}
171		if winReq.EstimatedFee != contestFee {
172			t.Fatalf("winner estimated fee = %d, want 60", winReq.EstimatedFee)
173		}
174		if winReq.ApproverAccountID != "payer" {
175			t.Fatalf("winner approver = %q, want payer", winReq.ApproverAccountID)
176		}
177		if !winReq.DecidedAt.Equal(approveAt) || !winReq.ReservedAt.Equal(approveAt) {
178			t.Fatalf("winner decided/reserved at %v/%v, want approve time %v",
179				winReq.DecidedAt, winReq.ReservedAt, approveAt)
180		}
181		// 批准成功保留原提交时刻与等待截止时刻。
182		if !winReq.CreatedAt.Equal(createdAt) || !winReq.WaitDeadline.Equal(waitDeadline) {
183			t.Fatalf("winner timing changed: created %v want %v, deadline %v want %v",
184				winReq.CreatedAt, createdAt, winReq.WaitDeadline, waitDeadline)
185		}
186		if winReq.RejectReason != "" {
187			t.Fatalf("reserved winner must not carry reject reason: %q", winReq.RejectReason)
188		}
189	
190		loseReq, err := w.Request(loser, contestRequestID)
191		if err != nil {
192			t.Fatal(err)
193		}
194		if loseReq.State != RequestPendingApproval {
195			t.Fatalf("loser %s state = %v, want still pending approval (must not become rejected)",
196				loser, loseReq.State)
197		}
198		// 失败批准不留任何决定、不开始预留计时。
199		if !loseReq.DecidedAt.IsZero() || loseReq.ApproverAccountID != "" || loseReq.RejectReason != "" {
200			t.Fatalf("loser decision fields changed on failed approve: %+v", loseReq)
201		}
202		if !loseReq.ReservedAt.IsZero() || loseReq.ReserveDuration != 0 || !loseReq.ReserveDeadline.IsZero() {
203			t.Fatalf("loser reserve timing started on failed approve: %+v", loseReq)
204		}
205		// 提交时间与等待截止时间保持原值。
206		if !loseReq.CreatedAt.Equal(createdAt) || !loseReq.WaitDeadline.Equal(waitDeadline) {
207			t.Fatalf("loser timing changed: created %v want %v, deadline %v want %v",
208				loseReq.CreatedAt, createdAt, loseReq.WaitDeadline, waitDeadline)
209		}
210		if loseReq.EstimatedFee != contestFee {
211			t.Fatalf("loser estimated fee = %d, want 60", loseReq.EstimatedFee)
212		}
213	
214		if bal, _ := w.Balance("payer"); bal != (Balances{Available: 140, Reserved: 60}) {
215			t.Fatalf("payer balance = %+v, want {140 60}", bal)
216		}
217		if pv, _ := w.Policy(contestPolicyID); pv.ReservedTotal != 60 || pv.SpentTotal != 0 {
218			t.Fatalf("policy totals = reserved %d spent %d, want 60/0", pv.ReservedTotal, pv.SpentTotal)
219		}
220	
221		// 账本：两条原待审批留痕 + 胜出请求的一条 60 预留 + 一条零金额批准，
222		// 共 4 条；失败批准不新增任何记录。
223		all := w.Ledger()
224		if len(all) != 4 {
225			t.Fatalf("ledger entries = %d, want 4 (2 pending + reserve + approval): %+v", len(all), all)
226		}
227		if got := countKind(all, LedgerPendingApproval); got != 2 {
228			t.Fatalf("pending entries = %d, want original 2 preserved", got)
229		}
230		if got := countKind(all, LedgerReserve); got != 1 {
231			t.Fatalf("reserve entries = %d, want exactly 1 for the winner", got)
232		}
233		if got := countKind(all, LedgerApproval); got != 1 {
234			t.Fatalf("approval entries = %d, want exactly 1 for the winner", got)
235		}
236		for _, kind := range []LedgerKind{LedgerRejection, LedgerRefund, LedgerSettle, LedgerExpiration, LedgerCancellation} {
237			if got := countKind(all, kind); got != 0 {
238				t.Fatalf("ledger kind %v entries = %d, want none after contested approvals", kind, got)
239			}
240		}
241		res, ok := ledgerEntryFor(all, LedgerReserve, contestRequestID)
242		if !ok {
243			t.Fatal("missing reserve entry for winner")
244		}
245		if res.AccountID != "payer" || res.Amount != 60 || !res.At.Equal(approveAt) {
246			t.Fatalf("winner reserve entry = %+v, want payer 60 at approve time", res)
247		}
248		app, ok := ledgerEntryFor(all, LedgerApproval, contestRequestID)
249		if !ok {
250			t.Fatal("missing zero-amount approval entry for winner")
251		}
252		if app.AccountID != winner || app.Amount != 0 || !app.At.Equal(approveAt) {
253			t.Fatalf("winner approval entry = %+v, want zero-amount entry for %s at approve time", app, winner)
254		}
255		// 两条待审批留痕仍分别归属 u1、u2，失败批准没有把失败方转成拒绝留痕。
256		pendingAccounts := map[string]int{}
257		for _, e := range all {
258			if e.Kind == LedgerPendingApproval {
259				pendingAccounts[e.AccountID]++
260			}
261		}
262		if pendingAccounts["u1"] != 1 || pendingAccounts["u2"] != 1 {
263			t.Fatalf("pending traces = %+v, want one each for u1 and u2", pendingAccounts)
264		}
265	}
