272	// TestSequentialContestedApprovalsOnlyOneSucceeds 顺序复现争用：在策略与会话
273	// 有效、等待期限未到的同一时刻连续批准两笔待审批请求，只能有一笔成功预留
274	// 60，另一笔返回可识别的 ErrQuotaExceeded 并继续待审批——不能转成拒绝终态，
275	// 也不能因出资账户余额充足（200 ≥ 120）就让两笔都获批。
276	func TestSequentialContestedApprovalsOnlyOneSucceeds(t *testing.T) {
277		for _, order := range []struct {
278			name        string
279			first       string
280			second      string
281			firstOK     bool
282			secondQuota bool
283		}{
284			{"u1-first", "u1", "u2", true, true},
285			{"u2-first", "u2", "u1", true, true},
286		} {
287			t.Run(order.name, func(t *testing.T) {
288				w, c, createdAt, waitDeadline := setupSharedQuotaApproveContest(t)
289				approveAt := c.t.Add(10 * time.Second)
290				c.t = approveAt
291	
292				first, err := approveContest(w, order.first)
293				if err != nil {
294					t.Fatalf("first approve by %s: %v", order.first, err)
295				}
296				if first.State != RequestReserved {
297					t.Fatalf("first approve state = %v, want reserved", first.State)
298				}
299				// 第二笔：payer 可用 140 ≥ 60，余额充足，但共享额度 60+60 = 120 > 100，
300				// 必须按超额度失败而非余额不足。
301				if _, err := approveContest(w, order.second); !errors.Is(err, ErrQuotaExceeded) {
302					t.Fatalf("second approve by %s err = %v, want ErrQuotaExceeded", order.second, err)
303				} else if errors.Is(err, ErrInsufficientBalance) {
304					t.Fatalf("second approve must fail on shared quota, not payer balance: %v", err)
305				}
306				checkContestOutcome(t, w, order.first, order.second, createdAt, waitDeadline, approveAt)
307	
308				// 期限内立即再次批准失败方：额度仍被胜出预留占用，依旧超额度、
309				// 依旧待审批，账本不增长。
310				ledgerBefore := len(w.Ledger())
311				if _, err := approveContest(w, order.second); !errors.Is(err, ErrQuotaExceeded) {
312					t.Fatalf("retry approve by %s err = %v, want ErrQuotaExceeded", order.second, err)
313				}
314				if len(w.Ledger()) != ledgerBefore {
315					t.Fatalf("retry approve grew ledger %d -> %d", ledgerBefore, len(w.Ledger()))
316				}
317				checkContestOutcome(t, w, order.first, order.second, createdAt, waitDeadline, approveAt)
318			})
319		}
320	}
