322	// raceApproveBias 控制两个批准 goroutine 的起跑方式，使“u1 先获批”与
323	// “u2 先获批”两种先后顺序都能在并发 harness 下被确定性地观察到：偏向模式下
324	// 后一个 goroutine 等前一个的 Approve 完全返回后才起跑，先后顺序不依赖
325	// 调度器或睡眠时间。
326	type raceApproveBias int
327	
328	const (
329		approveSimultaneous raceApproveBias = iota
330		approveU1First
331		approveU2First
332	)
333	
334	// raceContestedApprovals 用出资账户的同一个有效审批会话从两个 goroutine
335	// 同时批准 u1、u2 的待审批请求，断言恰有一笔成功、另一笔 ErrQuotaExceeded，
336	// 返回胜出与失败的使用账户编号。bias 用于确定性地覆盖两种先后顺序。
337	func raceContestedApprovals(t *testing.T, w *Wallet, bias raceApproveBias) (winner, loser string) {
338		t.Helper()
339		accounts := []string{"u1", "u2"}
340		views := make([]RequestView, 2)
341		errs := make([]error, 2)
342		gates := []chan struct{}{make(chan struct{}), make(chan struct{})}
343		done := []chan struct{}{make(chan struct{}), make(chan struct{})}
344	
345		var wg sync.WaitGroup
346		for i, account := range accounts {
347			i, account := i, account
348			wg.Add(1)
349			go func() {
350				defer wg.Done()
351				<-gates[i]
352				views[i], errs[i] = approveContest(w, account)
353				close(done[i])
354			}()
355		}
356		// 偏向模式下先放行指定的一方，并等它的批准完整结束后再放行另一方，
357		// 确定性地产生先后顺序；同时模式下两个闸门一起关闭。
358		switch bias {
359		case approveU1First:
360			close(gates[0])
361			<-done[0]
362			close(gates[1])
363		case approveU2First:
364			close(gates[1])
365			<-done[1]
366			close(gates[0])
367		default:
368			close(gates[0])
369			close(gates[1])
370		}
371		wg.Wait()
372	
373		successes := 0
374		for i, account := range accounts {
375			switch {
376			case errs[i] == nil:
377				successes++
378				winner = account
379				if views[i].State != RequestReserved || views[i].ApproverAccountID != "payer" {
380					t.Fatalf("winning approve view for %s = %+v, want reserved by payer", account, views[i])
381				}
382			case errors.Is(errs[i], ErrQuotaExceeded):
383				loser = account
384			default:
385				t.Fatalf("approve for %s err = %v, want nil or ErrQuotaExceeded", account, errs[i])
386			}
387		}
388		if successes != 1 || winner == "" || loser == "" {
389			t.Fatalf("contested approvals must yield exactly one success and one quota error, got winner %q loser %q errs %v",
390				winner, loser, errs)
391		}
392		return winner, loser
393	}
