395	// TestConcurrentContestedApprovalsAcrossAccounts 并发复现题述场景：出资账户
396	// 用有效审批会话同时批准两个不同使用账户的同号待审批请求时，只能有一笔
397	// 成功预留 60，另一笔返回 ErrQuotaExceeded 并继续待审批；无需指定哪名使用
398	// 账户先获批——u1 胜出与 u2 胜出两种结果都必须符合同一规则。三种起跑方式
399	// 各跑多轮，并要求两个账户都至少胜出一次，确保两种先后顺序都被真正验证。
400	func TestConcurrentContestedApprovalsAcrossAccounts(t *testing.T) {
401		const iterations = 24
402		wins := map[string]int{}
403		for _, bias := range []struct {
404			name string
405			mode raceApproveBias
406		}{
407			{"simultaneous", approveSimultaneous},
408			{"u1-first", approveU1First},
409			{"u2-first", approveU2First},
410		} {
411			for i := 0; i < iterations; i++ {
412				w, c, createdAt, waitDeadline := setupSharedQuotaApproveContest(t)
413				approveAt := c.t.Add(10 * time.Second)
414				c.t = approveAt
415	
416				winner, loser := raceContestedApprovals(t, w, bias.mode)
417				wins[winner]++
418				checkContestOutcome(t, w, winner, loser, createdAt, waitDeadline, approveAt)
419			}
420		}
421		if len(wins) != 2 {
422			t.Fatalf("each usage account must win at least once, got winner distribution %v", wins)
423		}
424		t.Logf("winner distribution: %v", wins)
425	}
