427	// TestContestedApproveSettleFreesQuotaForOther 验证题述的完整后续：胜出请求
428	// 按实际费用 40 结算后，差额 20 退回出资账户，策略只保留 40 已花费额度；
429	// 在等待期限内再批准另一笔时，现存预留 0 + 已花费 40 + 本次预留 60 恰好
430	// 等于累计上限 100，必须允许批准。最终 payer 可用 100 / 预留 60，策略
431	// 已花费 40 / 预留 60；前一笔保持已结算、后一笔成为已预留，账本中的扣减
432	// 与退款能够解释全部资金变化。两种胜出顺序适用同一规则，这里都覆盖。
433	func TestContestedApproveSettleFreesQuotaForOther(t *testing.T) {
434		for _, tc := range []struct {
435			name   string
436			winner string
437			loser  string
438		}{
439			{"u1-wins-then-u2-approved", "u1", "u2"},
440			{"u2-wins-then-u1-approved", "u2", "u1"},
441		} {
442			t.Run(tc.name, func(t *testing.T) {
443				w, c, createdAt, waitDeadline := setupSharedQuotaApproveContest(t)
444				approveAt := c.t.Add(10 * time.Second)
445				c.t = approveAt
446	
447				// 并发同时批准，用起跑偏向确定性地产生用例指定的胜出顺序；
448				// 两种胜出结果的统一规则已在并发测试中覆盖。
449				bias := approveU1First
450				if tc.winner == "u2" {
451					bias = approveU2First
452				}
453				winner, loser := raceContestedApprovals(t, w, bias)
454				if winner != tc.winner || loser != tc.loser {
455					t.Fatalf("biased race winner = %s loser = %s, want %s/%s", winner, loser, tc.winner, tc.loser)
456				}
457				checkContestOutcome(t, w, winner, loser, createdAt, waitDeadline, approveAt)
458	
459				// 胜出请求按实际费用 40 结算：扣 40、差额 20 退回 payer；
460				// 策略预留总额清零、已花费总额 40。
461				settleAt := approveAt.Add(10 * time.Second)
462				c.t = settleAt
463				settled, err := w.Settle(winner, contestRequestID, contestActualFee)
464				if err != nil {
465					t.Fatalf("settle winner %s: %v", winner, err)
466				}
467				if settled.State != RequestSettled || settled.ActualFee != contestActualFee {
468					t.Fatalf("settled view = %+v, want settled actual 40", settled)
469				}
470				if bal, _ := w.Balance("payer"); bal != (Balances{Available: 160, Reserved: 0}) {
471					t.Fatalf("payer balance after settle = %+v, want {160 0}", bal)
472				}
473				if pv, _ := w.Policy(contestPolicyID); pv.ReservedTotal != 0 || pv.SpentTotal != 40 {
474					t.Fatalf("policy totals after settle = reserved %d spent %d, want 0/40",
475						pv.ReservedTotal, pv.SpentTotal)
476				}
477	
478				// 失败方仍待审批，提交时间与等待截止时间保持原值，且仍在期限内
479				// （批准时刻早于 waitDeadline）。
480				pending, err := w.Request(loser, contestRequestID)
481				if err != nil {
482					t.Fatal(err)
483				}
484				if pending.State != RequestPendingApproval {
485					t.Fatalf("loser state after settle = %v, want still pending", pending.State)
486				}
487				if !pending.CreatedAt.Equal(createdAt) || !pending.WaitDeadline.Equal(waitDeadline) {
488					t.Fatalf("loser timing changed before second approve: %+v", pending)
489				}
490				if !settleAt.Before(waitDeadline) {
491					t.Fatalf("test setup: settle time %v must be within wait deadline %v", settleAt, waitDeadline)
492				}
493	
494				// 等待期限内再批准失败方：40 已花费 + 60 本次预留恰为 100 上限，
495				// 必须允许；余额 160 也足以预留 60。
496				secondApproveAt := settleAt.Add(10 * time.Second)
497				c.t = secondApproveAt
498				if !secondApproveAt.Before(waitDeadline) {
499					t.Fatalf("test setup: second approve %v must be within wait deadline %v", secondApproveAt, waitDeadline)
500				}
501				approved, err := approveContest(w, loser)
502				if err != nil {
503					t.Fatalf("approve loser %s after quota freed by settle: %v", loser, err)
504				}
505				if approved.State != RequestReserved {
506					t.Fatalf("second approved state = %v, want reserved", approved.State)
507				}
508	
509				// 最终：payer 可用 100 / 预留 60；策略已花费 40 / 预留 60。
510				if bal, _ := w.Balance("payer"); bal != (Balances{Available: 100, Reserved: 60}) {
511					t.Fatalf("final payer balance = %+v, want {100 60}", bal)
512				}
513				pv, _ := w.Policy(contestPolicyID)
514				if pv.ReservedTotal != 60 || pv.SpentTotal != 40 {
515					t.Fatalf("final policy totals = reserved %d spent %d, want 60/40", pv.ReservedTotal, pv.SpentTotal)
516				}
517				if pv.ReservedTotal+pv.SpentTotal != contestMaxTotal {
518					t.Fatalf("reserved+spent = %d, want exactly shared cap 100", pv.ReservedTotal+pv.SpentTotal)
519				}
520	
521				// 请求终态：前一笔保持已结算，后一笔成为已预留。
522				firstReq, err := w.Request(winner, contestRequestID)
523				if err != nil {
524					t.Fatal(err)
525				}
526				if firstReq.State != RequestSettled || firstReq.ActualFee != 40 {
527					t.Fatalf("winner final = %+v, want settled actual 40", firstReq)
528				}
529				secondReq, err := w.Request(loser, contestRequestID)
530				if err != nil {
531					t.Fatal(err)
532				}
533				if secondReq.State != RequestReserved || secondReq.ActualFee != 0 {
534					t.Fatalf("loser final = %+v, want reserved with no actual fee", secondReq)
535				}
536				if secondReq.ApproverAccountID != "payer" || !secondReq.ReservedAt.Equal(secondApproveAt) {
537					t.Fatalf("second approval decision fields = %+v", secondReq)
538				}
539				// 两笔的提交时间与等待截止时间始终保持申请时原值。
540				for _, r := range []RequestView{firstReq, secondReq} {
541					if !r.CreatedAt.Equal(createdAt) || !r.WaitDeadline.Equal(waitDeadline) {
542						t.Fatalf("request timing changed: %+v", r)
543					}
544				}
545	
546				// 账本逐条核对（按追加顺序）：
547				//  1. u1 待审批留痕（0）
548				//  2. u2 待审批留痕（0）
549				//  3. 胜出批准预留：payer -60（LedgerReserve, 60）
550				//  4. 胜出批准留痕：winner（LedgerApproval, 0）
551				//  5. 胜出结算扣减：payer（LedgerSettle, 40）
552				//  6. 胜出差额退款：payer（LedgerRefund, 20）
553				//  7. 第二笔批准预留：payer -60（LedgerReserve, 60）
554				//  8. 第二笔批准留痕：loser（LedgerApproval, 0）
555				all := w.Ledger()
556				if len(all) != 8 {
557					t.Fatalf("final ledger entries = %d, want 8: %+v", len(all), all)
558				}
559				if all[0].Kind != LedgerPendingApproval || all[0].AccountID != "u1" || all[0].Amount != 0 {
560					t.Fatalf("entry 0 = %+v, want u1 pending", all[0])
561				}
562				if all[1].Kind != LedgerPendingApproval || all[1].AccountID != "u2" || all[1].Amount != 0 {
563					t.Fatalf("entry 1 = %+v, want u2 pending", all[1])
564				}
565				if all[2].Kind != LedgerReserve || all[2].AccountID != "payer" || all[2].Amount != 60 || !all[2].At.Equal(approveAt) {
566					t.Fatalf("entry 2 = %+v, want payer reserve 60 at first approve", all[2])
567				}
568				if all[3].Kind != LedgerApproval || all[3].AccountID != winner || all[3].Amount != 0 {
569					t.Fatalf("entry 3 = %+v, want zero-amount approval for winner %s", all[3], winner)
570				}
571				if all[4].Kind != LedgerSettle || all[4].AccountID != "payer" || all[4].Amount != 40 || !all[4].At.Equal(settleAt) {
572					t.Fatalf("entry 4 = %+v, want payer settle 40", all[4])
573				}
574				if all[5].Kind != LedgerRefund || all[5].AccountID != "payer" || all[5].Amount != 20 || !all[5].At.Equal(settleAt) {
575					t.Fatalf("entry 5 = %+v, want payer refund 20", all[5])
576				}
577				if all[6].Kind != LedgerReserve || all[6].AccountID != "payer" || all[6].Amount != 60 || !all[6].At.Equal(secondApproveAt) {
578					t.Fatalf("entry 6 = %+v, want payer reserve 60 at second approve", all[6])
579				}
580				if all[7].Kind != LedgerApproval || all[7].AccountID != loser || all[7].Amount != 0 {
581					t.Fatalf("entry 7 = %+v, want zero-amount approval for loser %s", all[7], loser)
582				}
583	
584				// 出资账户账本的资金求和解释最终余额：
585				// 预留不改变可用总额；扣减 -40；退款 +20；现存预留合计 60。
586				// 可用 = 200 - 40 + 20 - 60 = 100，预留 = 60 + 60 - 60 = 60。
587				payerLedger := w.AccountLedger("payer")
588				var reservedSum, settledSum, refundedSum int64
589				for _, e := range payerLedger {
590					switch e.Kind {
591					case LedgerReserve:
592						reservedSum += e.Amount
593					case LedgerSettle:
594						settledSum += e.Amount
595					case LedgerRefund:
596						refundedSum += e.Amount
597					default:
598						t.Fatalf("unexpected payer ledger entry: %+v", e)
599					}
600				}
601				if reservedSum != 120 || settledSum != 40 || refundedSum != 20 {
602					t.Fatalf("payer money sums = reserved %d settled %d refunded %d, want 120/40/20",
603						reservedSum, settledSum, refundedSum)
604				}
605				// 可用 = 初始 - 两次预留 120 + 已结算退回的差额 20 = 100；
606				// 预留余额 = 预留合计 120 - 结算释放的（扣减 40 + 退款 20）= 60。
607				wantAvailable := contestPayerInit - reservedSum + refundedSum
608				wantReserved := reservedSum - (settledSum + refundedSum)
609				if wantAvailable != 100 || wantReserved != 60 {
610					t.Fatalf("ledger sums recompute balances = available %d reserved %d, want 100/60",
611						wantAvailable, wantReserved)
612				}
613				if bal, _ := w.Balance("payer"); bal.Available != wantAvailable || bal.Reserved != wantReserved {
614					t.Fatalf("ledger sums do not explain balances: %+v", bal)
615				}
616			})
617		}
618	}
