781	func TestApproveDirectlyReservedReturnsNotPending(t *testing.T) {
782		w, c := setupApproval(t)
783		// 关闭审批的策略：费用 20 也直接预留。
784		off := approvalPolicy(c)
785		off.ID = "p-off"
786		off.ApprovalThreshold = 0
787		off.ApprovalWait = 0
788		if err := w.SavePolicy(off); err != nil {
789			t.Fatal(err)
790		}
791	
792		// 费用恰好等于门槛（10）：直接预留，不进入待审批。
793		eq := approvalApply()
794		eq.RequestID = "r-eq"
795		eq.EstimatedFee = 10
796		if _, err := w.Apply(eq); err != nil {
797			t.Fatal(err)
798		}
799		// 费用低于门槛（9）：直接预留并随后结算。
800		low := approvalApply()
801		low.RequestID = "r-low"
802		low.EstimatedFee = 9
803		if _, err := w.Apply(low); err != nil {
804			t.Fatal(err)
805		}
806		if _, err := w.Settle("u1", "r-low", 9); err != nil {
807			t.Fatal(err)
808		}
809		// 关闭审批的策略：直接预留。
810		disabled := approvalApply()
811		disabled.PolicyID = "p-off"
812		disabled.RequestID = "r-off"
813		if _, err := w.Apply(disabled); err != nil {
814			t.Fatal(err)
815		}
816	
817		for _, rid := range []string{"r-eq", "r-low", "r-off"} {
818			before := len(w.Ledger())
819			viewBefore, err := w.Request("u1", rid)
820			if err != nil {
821				t.Fatal(err)
822			}
823			// 未经审批直接受理的请求不能批准：即使已预留或已结算，
824			// 也返回 ErrRequestNotPending 而不是伪装成重复批准成功。
825			if _, err := w.Approve("u1", rid, "sa", "dev-approve"); !errors.Is(err, ErrRequestNotPending) {
826				t.Fatalf("approve directly-accepted %s err = %v, want ErrRequestNotPending", rid, err)
827			}
828			// 状态、时间与决定信息保持不变，账本不增长。
829			viewAfter, _ := w.Request("u1", rid)
830			if viewAfter != viewBefore {
831				t.Fatalf("%s view changed by failed approve: %+v -> %+v", rid, viewBefore, viewAfter)
832			}
833			if len(w.Ledger()) != before {
834				t.Fatalf("%s ledger grew on failed approve", rid)
835			}
836		}
837		// 余额与策略累计不因这些调用变化：r-eq 预留 10、r-low 结算 9、
838		// r-off 预留 20。
839		bal, _ := w.Balance("payer")
840		if bal != (Balances{Available: 61, Reserved: 30}) {
841			t.Fatalf("balance = %+v, want {61 30}", bal)
842		}
843	
844		// 身份校验次序不变：直接受理的请求用无效会话调用仍先返回无权审批。
845		if _, err := w.Approve("u1", "r-eq", "s1", "dev1"); !errors.Is(err, ErrNotApprover) {
846			t.Fatalf("bad approver session err = %v, want ErrNotApprover", err)
847		}
848	
849		// 对照：真正超过门槛（11）的请求经批准后，重复批准仍幂等返回。
850		over := approvalApply()
851		over.RequestID = "r-over"
852		over.EstimatedFee = 11
853		if _, err := w.Apply(over); err != nil {
854			t.Fatal(err)
855		}
856		if _, err := w.Approve("u1", "r-over", "sa", "dev-approve"); err != nil {
857			t.Fatal(err)
858		}
859		first, err := w.Approve("u1", "r-over", "sa", "dev-approve")
860		if err != nil {
861			t.Fatalf("repeat approve of approved request: %v", err)
862		}
863		if first.State != RequestReserved || first.ApproverAccountID != "payer" {
864			t.Fatalf("repeat approve view = %+v", first)
865		}
866		// 结算后重复批准仍返回已有结果。
867		if _, err := w.Settle("u1", "r-over", 11); err != nil {
868			t.Fatal(err)
869		}
870		settled, err := w.Approve("u1", "r-over", "sa", "dev-approve")
871		if err != nil {
872			t.Fatalf("repeat approve of settled approved request: %v", err)
873		}
874		if settled.State != RequestSettled || settled.ApproverAccountID != "payer" {
875			t.Fatalf("settled repeat approve view = %+v", settled)
876		}
877	}
878	
879	func TestConcurrentApproveReject(t *testing.T) {
880		w, _ := setupApproval(t)
881		if _, err := w.Apply(approvalApply()); err != nil {
882			t.Fatal(err)
883		}
884	
885		var wg sync.WaitGroup
886		for i := 0; i < 8; i++ {
887			i := i
888			wg.Add(1)
889			go func() {
890				defer wg.Done()
891				if i%2 == 0 {
892					_, _ = w.Approve("u1", "r1", "sa", "dev-approve")
893				} else {
894					_, _ = w.Reject("u1", "r1", "sa", "dev-approve", "concurrent reject")
895				}
896			}()
897		}
898		wg.Wait()
899	
900		// 以账本为准：有且仅有一个决定（批准留痕或拒绝留痕），且只出现一次。
901		approvals, rejections := 0, 0
902		for _, e := range w.Ledger() {
903			switch e.Kind {
904			case LedgerApproval:
905				approvals++
906			case LedgerRejection:
907				rejections++
908			}
909		}
910		if approvals+rejections != 1 {
911			t.Fatalf("decisions = %d (approve %d reject %d), want exactly 1", approvals+rejections, approvals, rejections)
912		}
913		req, _ := w.Request("u1", "r1")
914		if approvals == 1 && req.State != RequestReserved {
915			t.Fatalf("approved but final state = %v", req.State)
916		}
917		if rejections == 1 && req.State != RequestRejected {
918			t.Fatalf("rejected but final state = %v", req.State)
919		}
920		// 余额与状态一致：批准则预留 20，拒绝则不动。
921		bal, _ := w.Balance("payer")
922		if req.State == RequestReserved {
923			if bal != (Balances{Available: 80, Reserved: 20}) {
924				t.Fatalf("balance = %+v, want {80 20}", bal)
925			}
926		} else {
927			if bal != (Balances{Available: 100, Reserved: 0}) {
928				t.Fatalf("balance = %+v, want untouched", bal)
929			}
930		}
931	}
932	
933	func TestConcurrentCancelApprove(t *testing.T) {
934		w, _ := setupApproval(t)
935		if _, err := w.Apply(approvalApply()); err != nil {
936			t.Fatal(err)
937		}
938	
939		var wg sync.WaitGroup
940		wg.Add(2)
941		var cancelErr, approveErr error
942		go func() { defer wg.Done(); _, cancelErr = w.Cancel("u1", "r1") }()
943		go func() { defer wg.Done(); _, approveErr = w.Approve("u1", "r1", "sa", "dev-approve") }()
944		wg.Wait()
945	
946		if cancelErr != nil {
947			t.Fatalf("cancel err = %v", cancelErr)
948		}
949		// 两种合法结局：
950		//  - 取消先完成：批准失败 ErrRequestNotPending，余额不动；
951		//  - 批准先完成：取消按已预留规则退回，余额全额退回。
952		bal, _ := w.Balance("payer")
953		if approveErr == nil {
954			// 批准先完成，随后取消退回全部预留。
955			if bal != (Balances{Available: 100, Reserved: 0}) {
956				t.Fatalf("balance = %+v, want full refund {100 0}", bal)
957			}
958			req, _ := w.Request("u1", "r1")
959			if req.State != RequestCancelled {
960				t.Fatalf("state = %v, want cancelled after approve-then-cancel", req.State)
961			}
962		} else if errors.Is(approveErr, ErrRequestNotPending) {
963			// 取消先完成，批准失败。
964			if bal != (Balances{Available: 100, Reserved: 0}) {
965				t.Fatalf("balance = %+v, want untouched {100 0}", bal)
966			}
967			req, _ := w.Request("u1", "r1")
968			if req.State != RequestCancelled {
969				t.Fatalf("state = %v, want cancelled", req.State)
970			}
971		} else {
972			t.Fatalf("unexpected approve err = %v", approveErr)
973		}
974	}
975	
976	func TestPendingDoesNotOccupySharedQuota(t *testing.T) {
977		w, _ := setupApproval(t)
978		// 多笔待审批不占用共享累计额度：直接预留仍可进行。
979		for i := 0; i < 3; i++ {
980			in := approvalApply()
981			in.RequestID = fmt.Sprintf("p%d", i)
982			if _, err := w.Apply(in); err != nil {
983				t.Fatal(err)
984			}
985		}
986		pv, _ := w.Policy("p-approval")
987		if pv.ReservedTotal != 0 {
988			t.Fatalf("pending occupies quota: reserved %d", pv.ReservedTotal)
989		}
990		// 直接预留一笔（费用等于门槛，不进入待审批）不受待审批影响。
991		reserved := approvalApply()
992		reserved.RequestID = "r-direct"
993		reserved.EstimatedFee = 10
994		if _, err := w.Apply(reserved); err != nil {
995			t.Fatal(err)
996		}
997		pv, _ = w.Policy("p-approval")
998		if pv.ReservedTotal != 10 {
